/// <summary>
/// SalesInvoiceLineV3Entity COC class
/// </summary>
[ExtensionOf(tableStr(SalesInvoiceLineV3Entity))]
final class METSalesInvoiceLineV3Entity_Extension
{
}

Method.Source:
    /// <summary>
    /// Map data fields to virtual fields
    /// </summary>
    public void postLoad()
    {
        next postLoad();

        changecompany(this.DataAreaId)
        {
            //MPJ_24809 Returns Claims
            SalesLine       metSalesLineStd, metSalesLineStdCalc;
            select firstonly METBrokenCaseForClaims from metSalesLineStd                
                where metSalesLineStd.InventTransIdReturn == this.METInventTransId;
            if(metSalesLineStd.METBrokenCaseForClaims)
            {
                while select metSalesLineStdCalc
                    where metSalesLineStdCalc.InventTransIdReturn == this.METInventTransId
                {
                
                    this.METCurrentClaimedQty   += UnitOfMeasureConverter::convert(metSalesLineStdCalc.SalesQty,
                                                   UnitOfMeasure::unitOfMeasureIdBySymbol(metSalesLineStdCalc.SalesUnit),
                        UnitOfMeasure::unitOfMeasureIdBySymbol(METCustParameters::Find().BrokenCaseReturnUnitOfMeasure),
                                                   NoYes::Yes, InventTable::itemProduct(metSalesLineStdCalc.ItemId), NoYes::Yes);
                }
                this.METBrokenCase  = true;
            }
            else
            {
                select sum(SalesQty) from metSalesLineStd
                    where metSalesLineStd.InventTransIdReturn == this.METInventTransId;
        
                this.METCurrentClaimedQty   = metSalesLineStd.SalesQty;
            }

            CustInvoiceTrans        custInvoiceTrans;

            select sum(LineAmount) from custInvoiceTrans
                where custInvoiceTrans.InvoiceId == this.InvoiceNumber;

            this.METInvoiceTotalAmount = custInvoiceTrans.LineAmount;
            
        }
		
    }

    /// <summary>
    /// MPJ_24809 Returns Claims
    /// </summary>
    /// <returns> barcode string value</returns>
    private static server str getSalesInvoiceLineGTIN()
    {
        str                 metBarcode;
        SysDictTable        metDictInventItemBarcode = new SysDictTable(tableNum(InventItemBarcode));
        str                 metItemId;
        str                 metUom;
        str                 metSqlQuery = 'SELECT TOP 1 %1 FROM %2 WHERE %2.%3 = %4 AND %2.%5 = %6';
              

        metItemId = SysComputedColumn::returnField(dataentityviewstr(SalesInvoiceLineV3Entity), dataEntityDataSourceStr(SalesInvoiceLineV3Entity, CustInvoiceTrans),
                        fieldStr(CustInvoiceTrans, ItemId));
        
        metUom = SysComputedColumn::returnField(dataentityviewstr(SalesInvoiceLineV3Entity), dataEntityDataSourceStr(SalesInvoiceLineV3Entity, CustInvoiceTrans),
                        fieldStr(CustInvoiceTrans, SalesUnit));
        
        metBarcode = strFmt(@metSqlQuery,
                            metDictInventItemBarcode.fieldName(fieldNum(InventItemBarcode, ItemBarCode), DbBackend::Sql),
                            metDictInventItemBarcode.name(DbBackend::Sql),
                            metDictInventItemBarcode.fieldName(fieldNum(InventItemBarcode, ItemId), DbBackend::Sql),
                            metItemId,
                            metDictInventItemBarcode.fieldName(fieldNum(InventItemBarcode, UnitId), DbBackend::Sql),
                            metUom);

        return metBarcode;
    }

    /// <summary>
    /// Get Sales Invoice Indicator
    /// Do modify the METInvoiceIndicator in the below query in case of any modifications to enum
    /// </summary>
    /// <returns>Indicator info</returns>
    private static str getSalesInvoiceIndicator()
    {
        str inventTransId = SysComputedColumn::returnField(tableStr(SalesInvoiceLineV3Entity),
                                                            tableStr(CustInvoiceTrans),
                                                            fieldStr(CustInvoiceTrans, InventTransId));

        //DictEnum dictEnum = new DictEnum(enumNum(METInvoiceIndicator));
        
        str salesLineInvIndicator = strFmt(@"SELECT LEFT(
                                                STUFF(
                                                    (
                                                        SELECT DISTINCT ',' + IndicatorValue
                                                        FROM
                                                        (
                                                            SELECT EV.NAME AS IndicatorValue
                                                            FROM METSALESINVOICEINDICATORVIEW M
                                                            JOIN ENUMIDTABLE EI
                                                                ON EI.NAME = 'METInvoiceIndicator'
                                                            JOIN ENUMVALUETABLE EV
                                                                ON EV.ENUMID = EI.ID
                                                               AND EV.ENUMVALUE = M.CimponentInvoiceIndicator
                                                            WHERE M.INVENTTRANSID = %1
                                                              AND EV.ENUMVALUE <> 0

                                                            UNION

                                                            SELECT MSL.Indicators AS IndicatorValue
                                                            FROM SALESLINE SL
                                                            JOIN METSALESLINE MSL
                                                                ON SL.RECID = MSL.SALESLINE
                                                            WHERE SL.INVENTTRANSID = %1
                                                              AND ISNULL(MSL.Indicators, '') <> ''
                                                        ) X
                                                        FOR XML PATH(''), TYPE
                                                    ).value('.', 'NVARCHAR(MAX)')
                                                , 1, 1, '')
                                            , 20)",
                                            inventTransId);

        return salesLineInvIndicator;


    }
